<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {useRouter} from 'vue-router'
import {reviewRouteQuery} from '@note-flow/core'
import {loadReviewData} from '../services/reviewDataSource'
import type {LoadedReviewData,ReviewEvent} from '../services/reviewData'
import {calendarActivities,calendarMonthDays,localDayKey,isoWeekNumber} from '../services/calendarMonth'
import {dailyCulture,type DailyWeather} from '../services/dailyBrief'
import {chinaHoliday,holidaySource} from '../services/chinaHolidays'
import {globalAreaUid} from '../services/globalAreaScope'
import {accountSessionRevision} from '../services/accountStorage'
import {currentProfile} from '../services/profiles'
const props=defineProps<{load?:typeof loadReviewData;initialDate?:string;journalNavigation?:boolean;compact?:boolean;almanac?:boolean;weather?:DailyWeather;clock?:Date;refreshKey?:number}>(),emit=defineEmits<{'select-date':[date:string];close:[]}>(),router=useRouter()
const today=()=>localDayKey(new Date()),anchor=ref(new Date(new Date().getFullYear(),new Date().getMonth(),1)),selected=ref(today())
if(props.initialDate&&/^\d{4}-\d{2}-\d{2}$/.test(props.initialDate)){const date=new Date(props.initialDate+'T12:00:00');if(!Number.isNaN(date.getTime())){anchor.value=new Date(date.getFullYear(),date.getMonth(),1);selected.value=props.initialDate}}
const data=ref<LoadedReviewData>({tasks:[],events:[]}),loading=ref(false),error=ref(''),timezone=Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC'
const days=computed(()=>calendarMonthDays(anchor.value).map(day=>({...day,lunar:props.almanac?dailyCulture(day.date):undefined,week:isoWeekNumber(day.date)}))),activities=computed(()=>calendarActivities(data.value,timezone,globalAreaUid.value))
const selectedData=computed(()=>activities.value.get(selected.value)),selectedHoliday=computed(()=>chinaHoliday(selected.value))
const selectedDate=computed(()=>new Date(selected.value+'T12:00:00'))
const selectedCulture=computed(()=>dailyCulture(selected.value===today()?(props.clock||new Date()):selectedDate.value))
const selectedWeekday=computed(()=>selectedDate.value.toLocaleDateString('zh-CN',{weekday:'long'}))
let generation=0,active=true
async function refresh(){
 const ticket=++generation,session=accountSessionRevision(),owner=currentProfile()?.storageKey,area=globalAreaUid.value
 data.value={tasks:[],events:[]};loading.value=true;error.value=''
 const current=()=>active&&ticket===generation&&session===accountSessionRevision()&&owner===currentProfile()?.storageKey&&area===globalAreaUid.value
 try{const value=await (props.load||loadReviewData)({periodType:'monthly',anchor:localDayKey(anchor.value),timezone,scope:area?{areaUid:area}:{all:true}});if(current())data.value=value}
 catch{if(current())error.value='每日记录加载失败，节假日仍可查看。请重试。'}
 finally{if(active&&ticket===generation)loading.value=false}
}
function changeMonth(offset:number){anchor.value=new Date(anchor.value.getFullYear(),anchor.value.getMonth()+offset,1);selected.value=localDayKey(anchor.value)}
function selectDay(day:ReturnType<typeof calendarMonthDays>[number]){selected.value=day.key;if(!day.current)anchor.value=new Date(day.date.getFullYear(),day.date.getMonth(),1)}
function goToday(){selected.value=today();anchor.value=new Date(new Date().getFullYear(),new Date().getMonth(),1)}
function openEvent(event:ReviewEvent){
 const source=event.source as {uid:string;projectUid?:string;taskUid?:string}
 if(event.kind==='task_completed')void router.push({path:'/tasks',query:{task:source.uid}})
 else if(event.kind==='focus')void router.push('/focus')
 else if(event.kind==='project_log')void router.push(`/projects/${encodeURIComponent(source.projectUid||'')}/logs`)
 else void router.push({path:'/logs',query:{date:selected.value}})
}
const labels:Record<ReviewEvent['kind'],string>={task_completed:'完成任务',focus:'专注',log_record:'日志',periodic_record:'周期记录',project_log:'项目日志',note_created:'笔记'}
watch([anchor,globalAreaUid],refresh)
watch(()=>props.refreshKey,refresh)
onMounted(()=>{void refresh();window.addEventListener('note-flow:workspace-change',refresh);window.addEventListener('note-flow:account-data-reset',refresh)})
onBeforeUnmount(()=>{active=false;generation++;window.removeEventListener('note-flow:workspace-change',refresh);window.removeEventListener('note-flow:account-data-reset',refresh)})
</script>
<template><main class="calendar-page" :class="{'is-compact':compact,'has-almanac':almanac}"><header class="calendar-page-header"><h2 v-if="!almanac">月历</h2><nav aria-label="选择月份"><button aria-label="上个月" @click="changeMonth(-1)">‹</button><strong>{{anchor.getFullYear()}} 年 {{anchor.getMonth()+1}} 月</strong><button aria-label="下个月" @click="changeMonth(1)">›</button><button @click="goToday">今天</button></nav><button v-if="!compact" :disabled="loading" @click="refresh">{{loading?'加载中…':'刷新'}}</button><button v-if="journalNavigation&&!compact" aria-label="收起月历" @click="emit('close')">收起</button></header><p v-if="!almanac" class="calendar-source">中国大陆 · <a v-if="anchor.getFullYear()===holidaySource.year" :href="holidaySource.url" target="_blank" rel="noopener noreferrer">{{holidaySource.title}}</a><span v-else>本年度放假调休数据尚未收录</span> · 日期按本机时区展示</p><p v-if="error" role="alert">{{error}} <button @click="refresh">重试</button></p><div class="calendar-layout"><section class="month-surface" aria-label="月历"><div class="month-week"><span v-if="almanac">周次</span><span v-for="label in ['一','二','三','四','五','六','日']" :key="label">周{{label}}</span></div><div class="month-grid"><template v-for="(day,index) in days" :key="day.key"><span v-if="almanac&&index%7===0" class="week-number">第 {{day.week}} 周</span><button :aria-label="day.key+(day.holiday?' '+day.holiday.label:'')" :aria-pressed="selected===day.key" :class="{outside:!day.current,today:day.key===today(),selected:selected===day.key}" @click="selectDay(day)"><time>{{day.date.getDate()}}</time><small v-if="almanac" class="lunar-day">{{day.lunar?.lunarDay==='初一'?day.lunar?.lunarMonth:day.lunar?.lunarDay}}</small><span v-if="day.holiday" class="holiday" :class="day.holiday.kind">{{compact?(day.holiday.kind==='workday'?'班':'休'):(day.holiday.kind==='workday'?'班 · 调休':'休 · '+day.holiday.label)}}</span><small v-if="!compact&&activities.get(day.key)?.tasks.length">任务 {{activities.get(day.key)?.tasks.length}}</small><small v-if="!compact&&activities.get(day.key)?.logs">日志 {{activities.get(day.key)?.logs}}</small><small v-if="!compact&&activities.get(day.key)?.focusMinutes">专注 {{Math.round(activities.get(day.key)!.focusMinutes)}} 分钟</small><i v-if="compact&&(activities.get(day.key)?.tasks.length||activities.get(day.key)?.events.length)" class="activity-dot" aria-label="有任务或记录"/></button></template></div></section><aside class="day-surface"><header><h2>{{almanac?`${selectedDate.getMonth()+1}月${selectedDate.getDate()}日`:selected}}</h2><span v-if="almanac" class="selected-weekday">{{selectedWeekday}}</span><span v-if="selectedHoliday&&!almanac" class="holiday" :class="selectedHoliday.kind">{{selectedHoliday.label}}</span></header><p v-if="almanac" class="selected-lunar">农历 {{selectedCulture.lunar}} · {{selectedCulture.yearName}}年 {{selectedCulture.zodiac}}年</p><p v-if="loading&&!almanac">正在加载每日记录…</p><template v-else-if="!error"><p v-if="compact&&!almanac" class="compact-day-summary">任务 {{selectedData?.tasks.length||0}} · 日志 {{selectedData?.logs||0}} · 专注 {{Math.round(selectedData?.focusMinutes||0)}} 分钟</p><template v-if="!compact"><h3>当天任务 · {{selectedData?.tasks.length||0}}</h3><p v-if="!selectedData?.tasks.length">没有安排任务</p><button v-for="task in selectedData?.tasks||[]" :key="task.uid" class="agenda-item" @click="router.push({path:'/tasks',query:{task:task.uid}})"><span>{{task.completed?'已完成':'待完成'}}</span>{{task.title}}</button><h3>日志与活动 · {{selectedData?.events.length||0}}</h3><p v-if="!selectedData?.events.length">当天没有记录</p><button v-for="event in selectedData?.events||[]" :key="event.uid" class="agenda-item" @click="openEvent(event)"><span>{{labels[event.kind]}}</span>{{event.kind==='project_log'?'项目日志':event.title}}</button></template></template><section v-if="almanac" class="almanac-detail"><div class="almanac-pillars"><span v-for="pillar in selectedCulture.pillars" :key="pillar.label"><small>{{pillar.label}}</small><b>{{pillar.label==='时柱'&&selected!==today()?'—':pillar.value}}</b></span></div><div class="almanac-facts"><span><small>节气</small><b>{{selectedCulture.term.current}}</b><small>{{selectedCulture.term.next}}</small></span><span class="almanac-weather"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="M10 24H8a6 6 0 0 1-.3-12A9 9 0 0 1 25 11a6.5 6.5 0 0 1 0 13h-3M13 24h6"/></svg><b>{{selected===today()?(weather?.label||'暂未获取天气'):'仅提供今日天气'}}</b><small>{{selected===today()?(weather?.detail||weather?.advice||'允许定位后可显示本地天气'):'所选日期不提供天气预报'}}</small></span></div><div class="almanac-activities"><span><b>宜</b>{{selectedCulture.suitable.join('、')}}</span><span><b>忌</b>{{selectedCulture.avoid}}</span></div><small class="almanac-source" title="干支与节气按本地规则估算；宜忌为民俗参考">数据来源：本地历法 · {{weather?.source||'Open-Meteo'}}<template v-if="anchor.getFullYear()!==holidaySource.year"> · 本年度调休未收录</template></small></section><button v-if="!almanac&&(journalNavigation||compact)" class="daily-review" @click="emit('select-date',selected)">查看当天日志</button><button v-if="!almanac" class="daily-review" @click="router.push({path:'/reviews',query:reviewRouteQuery({period:'daily',anchor:selected,scope:globalAreaUid?{kind:'area',areaUid:globalAreaUid}:{kind:'personal'}})})">查看当天回顾</button></aside></div></main></template>
<style scoped>
