uted)}.day-surface .agenda-item{display:flex;flex-direction:column;gap:4px;width:100%;text-align:left;line-height:1.5;margin:6px 0;overflow-wrap:anywhere}.agenda-item span{font-size:11px;color:var(--pc-muted)}.daily-review{margin-top:20px}@media(max-width:1000px){.calendar-layout{grid-template-columns:minmax(0,1fr)}.month-grid>button{padding:7px;min-height:90px}}@media(max-width:600px){.calendar-page{padding:12px}.calendar-page-header nav{gap:7px}.month-grid>button{padding:5px;min-height:85px}.month-grid small,.holiday{font-size:10px}}
</style>

<style scoped>
.is-compact.calendar-page{height:auto;padding:14px;gap:9px;overflow:visible}.is-compact .calendar-page-header{display:grid;grid-template-columns:1fr auto;gap:8px}.is-compact .calendar-page-header h2{font-size:14px}.is-compact .calendar-page-header nav{grid-column:1/-1;grid-row:2;gap:6px}.is-compact .calendar-page-header nav strong{flex:1;font-size:12px;text-align:center}.is-compact button{font-size:11px;padding:4px 7px}.is-compact .calendar-source{font-size:10px;line-height:1.5}.is-compact .calendar-layout{grid-template-columns:minmax(0,1fr);gap:8px}.is-compact .month-surface,.is-compact .day-surface{border:0;border-radius:0}.is-compact .month-week span{font-size:10px;padding:5px 0}.is-compact .month-grid>button{position:relative;align-items:center;justify-content:center;min-height:32px;padding:3px;gap:0;border:0;border-radius:5px}.is-compact .month-grid time{font-size:12px}.is-compact .month-grid .holiday{position:absolute;top:1px;right:2px;font-size:8px}.is-compact .activity-dot{position:absolute;bottom:2px;width:3px;height:3px;border-radius:50%;background:var(--pc-primary)}.is-compact .day-surface{padding:9px 0 0;border-top:1px solid var(--pc-border);overflow:visible;display:flex;flex-wrap:wrap;align-items:center;gap:6px}.is-compact .day-surface header{display:flex;align-items:center;gap:6px;width:100%}.is-compact .day-surface h2{font-size:12px;margin:0}.is-compact .compact-day-summary{margin:2px 0;width:100%;font-size:11px}.is-compact .daily-review{margin-top:0}
</style>

